import{_ as p,a0 as r,w as l,s as i,I as a,x as t,a1 as e,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"學習用 Thonny 寫代碼： 一個面向初學者的Python IDE | LCTT x X-CMD","titleTemplate":false,"description":"學習用 Thonny 寫代碼： 一個面向初學者的Python IDE | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"學習用 Thonny 寫代碼： 一個面向初學者的Python IDE | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"學習用 Thonny 寫代碼： 一個面向初學者的Python IDE | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180219 Learn to code with Thonny - a Python IDE for beginners","title":"學習用 Thonny 寫代碼： 一個面向初學者的Python IDE","tag":"201806","desc":""},"relativePath":"201806/20180219 Learn to code with Thonny - a Python IDE for beginners.md","filePath":"[post].md"}'),h={name:"201806/20180219 Learn to code with Thonny - a Python IDE for beginners.md"};function y(u,n,g,b,f,c){const s=r("Link");return l(),i("div",null,[n[19]||(n[19]=a("h1",{id:"學習用-thonny-寫代碼-一個面向初學者的python-ide",tabindex:"-1"},[t("學習用 Thonny 寫代碼： 一個面向初學者的Python IDE "),a("a",{class:"header-anchor",href:"#學習用-thonny-寫代碼-一個面向初學者的python-ide","aria-label":"Permalink to “學習用 Thonny 寫代碼： 一個面向初學者的Python IDE”"},"​")],-1)),n[20]||(n[20]=a("p",null,[a("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/02/thonny.png-945x400.jpg",alt:""})],-1)),n[21]||(n[21]=a("p",null,"學習編程很難。即使當你最終怎麼正確使用你的冒號和括號，但仍然有很大的可能你的程序不會如果所想的工作。 通常，這意味着你忽略了某些東西或者誤解了語言結構，你需要在代碼中找到你的期望與現實存在分歧的地方。",-1)),n[22]||(n[22]=a("p",null,[t("程序員通常使用被叫做"),a("ruby",null,[t("調試器"),a("rt",null,"debugger")]),t("的工具來處理這種情況，它允許一步一步地運行他們的程序。不幸的是，大多數調試器都針對專業用途進行了優化，並假設用户已經很好地瞭解了語言結構的語義（例如：函數調用）。")],-1)),a("p",null,[n[1]||(n[1]=t("Thonny 是一個適合初學者的 Python IDE，由愛沙尼亞的 ",-1)),e(s,{href:"https://www.ut.ee/en"},{default:o(()=>[...n[0]||(n[0]=[t("Tartu 大學",-1)])]),_:1}),n[2]||(n[2]=t(" 開發，它採用了不同的方法，因為它的調試器是專為學習和教學編程而設計的。",-1))]),n[23]||(n[23]=d(`<p>雖然 Thonny 適用於像小白一樣的初學者，但這篇文章面向那些至少具有 Python 或其他命令式語言經驗的讀者。</p><h3 id="開始" tabindex="-1">開始 <a class="header-anchor" href="#開始" aria-label="Permalink to “開始”">​</a></h3><p>從第 Fedora 27 開始，Thonny 就被包含在 Fedora 軟件庫中。 使用 <code>sudo dnf install thonny</code> 或者你選擇的圖形工具（比如“<ruby>軟件<rt>Software</rt></ruby>”）安裝它。</p><p>當第一次啓動 Thonny 時，它會做一些準備工作，然後呈現一個空白的編輯器和 Python shell 。將下列程序文本複製到編輯器中，並將其保存到文件中（<code>Ctrl+S</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>n = 1</span></span>
<span class="line"><span>while n &lt; 5:</span></span>
<span class="line"><span>    print(n * &quot;*&quot;)</span></span>
<span class="line"><span>    n = n + 1</span></span></code></pre></div><p>我們首先運行該程序。 為此請按鍵盤上的 <code>F5</code> 鍵。 你應該看到一個由星號組成的三角形出現在 shell 窗格中。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/scr1.png" alt="一個簡單的 Thonny 程序"></p><p>Python 分析了你的代碼並理解了你想打印一個三角形了嗎？讓我們看看！</p><p>首先從“<ruby>查看<rt>View</rt></ruby>”菜單中選擇“<ruby>變量<rt>Variables</rt></ruby>”。這將打開一張表格，向我們展示 Python 是如何管理程序的變量的。現在通過按 <code>Ctrl + F5</code>（在 XFCE 中是 <code>Ctrl + Shift + F5</code>）以調試模式運行程序。在這種模式下，Thonny 使 Python 在每一步所需的步驟之前暫停。你應該看到程序的第一行被一個框包圍。我們將這稱為焦點，它表明 Python 將接下來要執行的部分代碼。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/thonny-scr2.png" alt=" Thonny 調試器焦點 "></p><p>你在焦點框中看到的一段代碼段被稱為賦值語句。 對於這種聲明，Python 應該計算右邊的表達式，並將值存儲在左邊顯示的名稱下。按 <code>F7</code> 進行下一步。你將看到 Python 將重點放在語句的正確部分。在這個例子中，表達式實際上很簡單，但是為了通用性，Thonny 提供了表達式計算框，它允許將表達式轉換為值。再次按 <code>F7</code> 將文字 <code>1</code> 轉換為值 <code>1</code>。現在 Python 已經準備好執行實際的賦值—再次按 <code>F7</code>，你應該會看到變量 <code>n</code> 的值為 <code>1</code> 的變量出現在變量表中。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/thonny-scr3.png" alt="Thonny 變量表"></p><p>繼續按 <code>F7</code> 並觀察 Python 如何以非常小的步驟前進。它看起來像是理解你的代碼的目的或者更像是一個愚蠢的遵循簡單規則的機器？</p><h3 id="函數調用" tabindex="-1">函數調用 <a class="header-anchor" href="#函數調用" aria-label="Permalink to “函數調用”">​</a></h3><p><ruby>函數調用<rt>Function Call</rt></ruby>是一種編程概念，它常常給初學者帶來很大的困惑。從表面上看，沒有什麼複雜的事情——給代碼命名，然後在代碼中的其他地方引用它（調用它）。傳統的調試器告訴我們，當你進入調用時，焦點跳轉到函數定義中（然後稍後神奇地返回到原來的位置）。這是整件事嗎？這需要我們關心嗎？</p><p>結果證明，“跳轉模型” 只對最簡單的函數是足夠的。理解參數傳遞、局部變量、返回和遞歸都得理解堆棧框架的概念。幸運的是，Thonny 可以直觀地解釋這個概念，而無需在厚厚的掩蓋下搜索重要的細節。</p><p>將以下遞歸程序複製到 Thonny 並以調試模式（<code>Ctrl+F5</code> 或 <code>Ctrl+Shift+F5</code>）運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def factorial(n):</span></span>
<span class="line"><span>    if n == 0:</span></span>
<span class="line"><span>        return 1</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        return factorial(n-1) * n</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(factorial(4))</span></span></code></pre></div><p>重複按 <code>F7</code>，直到你在對話框中看到表達式 <code>factorial(4)</code>。 當你進行下一步時，你會看到 Thonny 打開一個包含了函數代碼、另一個變量表和另一個焦點框的新窗口（移動窗口以查看舊的焦點框仍然存在）。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/thonny-scr4.png" alt="通過遞歸函數的 Thonny"></p><p>此窗口表示堆棧幀，即用於解析函數調用的工作區。幾個放在彼此頂部的這樣的窗口稱為<ruby>調用堆棧<rt>call stack</rt></ruby>。注意調用位置的參數 <code>4</code> 與 “局部變量” 表中的輸入 <code>n</code> 之間的關係。繼續按 <code>F7</code> 步進, 觀察在每次調用時如何創建新窗口並在函數代碼完成時被銷燬，以及如何用返回值替換了調用位置。</p><h3 id="值與參考" tabindex="-1">值與參考 <a class="header-anchor" href="#值與參考" aria-label="Permalink to “值與參考”">​</a></h3><p>現在，讓我們在 Python shell 中進行一個實驗。首先輸入下面屏幕截圖中顯示的語句：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/thonny-scr5.png" alt="Thonny shell 顯示列表突變"></p><p>正如你所看到的, 我們追加到列表 <code>b</code>, 但列表 <code>a</code> 也得到了更新。你可能知道為什麼會發生這種情況, 但是對初學者來説，什麼才是最好的解釋呢？</p><p>當教我的學生列表時，我告訴他們我一直欺騙了他們關於 Python 內存模型。實際上，它並不像變量表所顯示的那樣簡單。我告訴他們重新啓動解釋器（工具欄上的紅色按鈕），從“<ruby>查看<rt>View</rt></ruby>”菜單中選擇“<ruby>堆<rt>Heap</rt></ruby>”，然後再次進行相同的實驗。如果這樣做，你就會發現變量表不再包含值——它們實際上位於另一個名為“<ruby>堆<rt>Heap</rt></ruby>”的表中。變量表的作用實際上是將變量名映射到地址（或稱 ID），地址又指向了<ruby>堆<rt>Heap</rt></ruby>表中的行。由於賦值僅更改變量表，因此語句 <code>b = a</code> 只複製對列表的引用，而不是列表本身。這解釋了為什麼我們通過這兩個變量看到了變化。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2017/12/thonny-scr6.png" alt="在堆模式中的 Thonny"></p><p>（為什麼我要在教列表的主題之前推遲説出內存模型的事實？Python 存儲的列表是否有所不同？請繼續使用 Thonny 的堆模式來找出結果！在評論中告訴我你認為怎麼樣！）</p><p>如果要更深入地瞭解參考系統, 請將以下程序通過打開堆表複製到 Thonny 並進行小步調試（<code>F7</code>） 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def do_something(lst, x):</span></span>
<span class="line"><span>    lst.append(x)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>a = [1,2,3]</span></span>
<span class="line"><span>n = 4</span></span>
<span class="line"><span>do_something(a, n)</span></span>
<span class="line"><span>print(a)</span></span></code></pre></div><p>即使“堆模式”向我們顯示真實的圖片，但它使用起來也相當不方便。 因此，我建議你現在切換回普通模式（取消選擇“<ruby>查看<rt>View</rt></ruby>”菜單中的“<ruby>堆<rt>Heap</rt></ruby>”），但請記住，真實模型包含變量、參考和值。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>我在這篇文章中提及到的特性是創建 Thonny 的主要原因。很容易對函數調用和引用形成錯誤的理解，但傳統的調試器並不能真正幫助減少混淆。</p>`,33)),a("p",null,[n[4]||(n[4]=t("除了這些顯著的特性，Thonny 還提供了其他幾個初學者友好的工具。 請查看 ",-1)),e(s,{href:"http://thonny.org"},{default:o(()=>[...n[3]||(n[3]=[t("Thonny的主頁",-1)])]),_:1}),n[5]||(n[5]=t(" 以瞭解更多信息！",-1))]),n[24]||(n[24]=a("hr",null,null,-1)),a("p",null,[n[7]||(n[7]=t("via: ",-1)),e(s,{href:"https://fedoramagazine.org/learn-code-thonny-python-ide-beginners/"},{default:o(()=>[...n[6]||(n[6]=[t("https://fedoramagazine.org/learn-code-thonny-python-ide-beginners/",-1)])]),_:1})]),a("p",null,[n[11]||(n[11]=t("作者：",-1)),e(s,{href:"https://fedoramagazine.org/"},{default:o(()=>[...n[8]||(n[8]=[t("Aivar Annamaa",-1)])]),_:1}),n[12]||(n[12]=t(" 譯者：",-1)),e(s,{href:"https://github.com/Auk7F7"},{default:o(()=>[...n[9]||(n[9]=[t("Auk7F7",-1)])]),_:1}),n[13]||(n[13]=t(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:o(()=>[...n[10]||(n[10]=[t("wxy",-1)])]),_:1})]),a("p",null,[n[16]||(n[16]=t("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[14]||(n[14]=[t("LCTT",-1)])]),_:1}),n[17]||(n[17]=t(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:o(()=>[...n[15]||(n[15]=[t("Linux中國",-1)])]),_:1}),n[18]||(n[18]=t(" 榮譽推出",-1))])])}const P=p(h,[["render",y]]);export{k as __pageData,P as default};
